struct GemvB64Image {
  CUmodule mod = nullptr;
  std::unordered_map<int, CUfunction> plain;
  std::unordered_map<int, CUfunction> sk;
  std::unordered_map<int, CUfunction> sk_red;
  std::unordered_map<int, CUfunction> skf;
  LaunchFn launch = nullptr;

  GemvB64Image() {
    void* h = dlopen("libcuda.so.1", RTLD_NOW | RTLD_GLOBAL);
    if (h == nullptr) {
      printf("e3m4 b64x64 gemv: cannot dlopen libcuda.so.1\n");
      return;
    }
    auto load = reinterpret_cast<ModuleLoadFn>(dlsym(h, "cuModuleLoadData"));
    auto getf = reinterpret_cast<GetFuncFn>(dlsym(h, "cuModuleGetFunction"));
    launch = reinterpret_cast<LaunchFn>(dlsym(h, "cuLaunchKernel"));
    if (load == nullptr || getf == nullptr || launch == nullptr) {
      printf("e3m4 b64x64 gemv: driver entry points missing\n");
      return;
    }
    if (load(&mod, kGemvB64Cubin) != CUDA_SUCCESS) {
      printf("e3m4 b64x64 gemv: image load failed\n");
      mod = nullptr;
      return;
    }
    for (int k : {320, 2560, 10240}) {
      char nm[64];
      snprintf(nm, sizeof(nm), "e3m4b64x64_gemv_%d", k);
      CUfunction fn = nullptr;
      if (getf(&fn, mod, nm) == CUDA_SUCCESS) plain[k] = fn;
    }
    for (int k : {2560, 10240}) {
      char nm[64];
      CUfunction f1 = nullptr, f2 = nullptr, f3 = nullptr;
      snprintf(nm, sizeof(nm), "gemv_sk64_%d", k);
      if (getf(&f1, mod, nm) == CUDA_SUCCESS) sk[k] = f1;
      snprintf(nm, sizeof(nm), "gemv_sk64_%d_reduce", k);
      if (getf(&f2, mod, nm) == CUDA_SUCCESS) sk_red[k] = f2;
      snprintf(nm, sizeof(nm), "gemv_skf64_%d", k);
      if (getf(&f3, mod, nm) == CUDA_SUCCESS) skf[k] = f3;
    }
  }
};

GemvB64Image& gemv_b64_image() {
  static GemvB64Image img;
  return img;
}

// split-K factor baked into each cubin entry (gemv_core<K, S, true>).
int b64_gemv_sk(int k) { return k == 10240 ? 8 : (k == 2560 ? 5 : 0); }


}  // namespace

struct Sm120Fp8E3m4GemvB64 {
  // out[M,N] bf16 = x bf16 [M,K] . dequant(w e3m4 [N,K], w_s fp32 [cN64,K64])^T
  static void
  run(const tvm::ffi::TensorView out,
      const tvm::ffi::TensorView x_bf16,
      const tvm::ffi::TensorView w_e3m4,
      const tvm::ffi::TensorView w_scale) {
    using namespace host;
    auto device = SymbolicDevice{};
    device.set_options<kDLCUDA>();
    const int M = static_cast<int>(x_bf16.shape()[0]);
    const int K = static_cast<int>(x_bf16.shape()[1]);
    const int N = static_cast<int>(w_e3m4.shape()[0]);
    TensorMatcher({M, K}).with_dtype<bf16_t>().with_device(device).verify(x_bf16);
    TensorMatcher({N, K}).verify(w_e3m4);
    TensorMatcher({(N + 63) / 64, K / 64}).with_dtype<fp32_t>()
        .with_device(device).verify(w_scale);
    TensorMatcher({M, N}).with_dtype<bf16_t>().with_device(device).verify(out);

    auto& img = gemv_b64_image();
    host::RuntimeCheck(img.mod != nullptr, "e3m4 b64x64 gemv image unavailable");
    auto it = img.plain.find(K);
    host::RuntimeCheck(it != img.plain.end(), "e3m4 b64x64 gemv: no entry for K=", K);
    auto stream = host::LaunchKernel::resolve_device(device.unwrap());

    void* xp = x_bf16.data_ptr();
    void* wp = w_e3m4.data_ptr();
    void* sp = w_scale.data_ptr();
    void* op = out.data_ptr();
    int n = N, m = M;
    void* kp[] = {&op, &xp, &wp, &sp, &n, &m};
    CUresult rc = img.launch(it->second, 1, static_cast<unsigned>((N + 7) / 8), 1,
                             256, 1, 1, 0, static_cast<CUstream>(stream), kp, nullptr);
    host::RuntimeCheck(rc == CUDA_SUCCESS, "e3m4 b64x64 gemv launch failed: ",
                       static_cast<int>(rc));
  }
};

struct Sm120Fp8E3m4GemvB64Sk {
  // FUSED split-K: one kernel. atomicAdd partials into persistent fp32
  // acc[M,N]; the last z-block per row (sem[n]==S-1) writes bf16 out and
  // self-cleans acc/sem, so graph replay is safe with no zeroing kernel.
  // acc/sem are caller-owned and must be zero on first call (torch.zeros).
  static void
  run(const tvm::ffi::TensorView out,
      const tvm::ffi::TensorView acc,
      const tvm::ffi::TensorView sem,
      const tvm::ffi::TensorView x_bf16,
      const tvm::ffi::TensorView w_e3m4,
      const tvm::ffi::TensorView w_scale) {
    using namespace host;
    auto device = SymbolicDevice{};
    device.set_options<kDLCUDA>();
    const int M = static_cast<int>(x_bf16.shape()[0]);
    const int K = static_cast<int>(x_bf16.shape()[1]);
    const int N = static_cast<int>(w_e3m4.shape()[0]);
    TensorMatcher({M, K}).with_dtype<bf16_t>().with_device(device).verify(x_bf16);
    TensorMatcher({N, K}).verify(w_e3m4);
    TensorMatcher({(N + 63) / 64, K / 64}).with_dtype<fp32_t>()
        .with_device(device).verify(w_scale);
    TensorMatcher({M, N}).with_dtype<bf16_t>().with_device(device).verify(out);
    const int s = b64_gemv_sk(K);
    host::RuntimeCheck(s > 0, "e3m4 b64x64 gemv sk: no entry for K=", K);
    TensorMatcher({M, N}).with_dtype<fp32_t>().with_device(device).verify(acc);
    // int32 scratch (bit-compatible with the kernel's unsigned*); no dtype
    // matcher — the buffer is allocated by the Python op, never user input.
    TensorMatcher({N}).with_device(device).verify(sem);

    auto& img = gemv_b64_image();
    auto kf = img.skf.find(K);
    host::RuntimeCheck(img.mod != nullptr && kf != img.skf.end(),
                       "e3m4 b64x64 gemv fused entry unavailable for K=", K);
    auto stream = host::LaunchKernel::resolve_device(device.unwrap());

    void* op = out.data_ptr();
    void* ap = acc.data_ptr();
    void* sp2 = sem.data_ptr();
    void* xp = x_bf16.data_ptr();
    void* wp = w_e3m4.data_ptr();
    void* sp = w_scale.data_ptr();
    int n = N, m = M;
    void* kp[] = {&op, &ap, &sp2, &xp, &wp, &sp, &n, &m};
    CUresult rc = img.launch(kf->second, 1, static_cast<unsigned>((N + 7) / 8),
                             static_cast<unsigned>(s), 256, 1, 1, 0,
                             static_cast<CUstream>(stream), kp, nullptr);
    host::RuntimeCheck(rc == CUDA_SUCCESS, "e3m4 b64x64 gemv fused launch failed: ",
                       static_cast<int>(rc));
  }
};

}  // namespace sglang
